def find_path(graph, start, goal):
    if start not in graph:
        return None
    queue = [(start, [start])]
    visited = set()
    while queue:
        node, path = queue.pop(0)
        if node in visited:
            continue
        visited.add(node)
        if node == goal:
            return path
        for neighbor in graph[node]:
            if neighbor not in visited:
                new_path = path + [neighbor]
                queue.append((neighbor, new_path))
    return None
